from collections import Counter
from math import inf


class Solution:
    def minChanges(self, nums: List[int], k: int) -> int:
        MAXX = 1 << 10
        freq = [Counter() for _ in range(k)]
        size = [0] * k
        for i, x in enumerate(nums):
            freq[i % k][x] += 1
            size[i % k] += 1

        dp = [inf] * MAXX
        dp[0] = 0
        for j in range(k):
            best = min(dp)
            ndp = [size[j] + best] * MAXX
            for v, c in freq[j].items():
                keep = size[j] - c
                for x in range(MAXX):
                    cand = dp[x ^ v] + keep
                    if cand < ndp[x]:
                        ndp[x] = cand
            dp = ndp
        return dp[0]

