        vector<int> dp(MAXX, INF);
        dp[0] = 0;
        for (int j = 0; j < k; j++) {
            int mn = *min_element(dp.begin(), dp.end());
            vector<int> ndp(MAXX, mn + sz[j]);
            for (int v = 0; v < MAXX; v++) {
                int c = cnt[j][v];
                if (!c) continue;
                int keep = sz[j] - c;
                for (int x = 0; x < MAXX; x++)
