class Solution {
    public int minChanges(int[] nums, int k) {
        final int MAXX = 1 << 10, INF = Integer.MAX_VALUE / 2;
        int[][] cnt = new int[k][MAXX];
        int[] sz = new int[k];
        for (int i = 0; i < nums.length; i++) {
            cnt[i % k][nums[i]]++;
            sz[i % k]++;
        }
        int[] dp = new int[MAXX];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int j = 0; j < k; j++) {
            int mn = Integer.MAX_VALUE;
            for (int x = 0; x < MAXX; x++) mn = Math.min(mn, dp[x]);
            int[] ndp = new int[MAXX];
            Arrays.fill(ndp, mn + sz[j]);
            for (int v = 0; v < MAXX; v++) {
                if (cnt[j][v] == 0) continue;
                int keep = sz[j] - cnt[j][v];
                for (int x = 0; x < MAXX; x++)
                    ndp[x] = Math.min(ndp[x], dp[x ^ v] + keep);
            }
            dp = ndp;
        }
        return dp[0];
    }
}

