/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number}
 */
var minChanges = function(nums, k) {
    const MAXX = 1 << 10;
    const freq = Array.from({ length: k }, () => new Map());
    const size = new Array(k).fill(0);
    nums.forEach((x, i) => {
        const f = freq[i % k];
        f.set(x, (f.get(x) || 0) + 1);
        size[i % k]++;
    });
    let dp = new Array(MAXX).fill(Infinity);
    dp[0] = 0;
    for (let j = 0; j < k; j++) {
        const base = Math.min(...dp) + size[j];
        const ndp = new Array(MAXX).fill(base);
        for (const [v, c] of freq[j]) {
            const keep = size[j] - c;
            for (let x = 0; x < MAXX; x++) {
                const cand = dp[x ^ v] + keep;
                if (cand < ndp[x]) ndp[x] = cand;
            }
        }
        dp = ndp;
    }
    return dp[0];
};
